*,
*::after,
*::before,
.modal {
  font-family: 'Poppins', sans-serif;
  /* font-family: "Jost", sans-serif; */
  font-weight: 400;
  font-style: normal;
}

.App {
  text-align: center;
}

.App-logo {
  height: 40vmin;
  pointer-events: none;
}

@media (prefers-reduced-motion: no-preference) {
  .App-logo {
    animation: App-logo-spin infinite 20s linear;
  }
}

.App-header {
  background-color: #282c34;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: calc(10px + 2vmin);
  color: white;
}

.App-link {
  color: #61dafb;
}

@keyframes App-logo-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.chat-dark:hover {
  background-color: #495057 !important; /* A darker shade of Bootstrap's secondary */
  transition: background-color 0.2s ease-in-out;
}

.chat-light:hover {
  background-color: rgba(0, 0, 0, 0.4) !important; /* A darker shade of Bootstrap's secondary */
  /* color: white !important; */
  transition:
    background-color 0.2s,
    color 0.2s ease-in-out;
}

.overlay_screenshot {
  position: relative;
  z-index: 0;
  &::before {
    position: absolute;
    content: '';
    width: 100%;
    top: 0;
    left: 0;
    height: 100vh;
    z-index: 1;
    background-color: rgba(0, 0, 0, 0.9);
  }
}
